import numpy as np
def read(p):
    lines=open(p).read().splitlines()
    n=int(lines[0]); els=[];xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return els,np.array(xyz)
els,pos=read("opt3.xyz")
print("O31-H74:", round(np.linalg.norm(pos[31]-pos[74]),2))
# find any H near O31
for i,e in enumerate(els):
    if e=="H":
        d=np.linalg.norm(pos[i]-pos[31])
        if d<1.6: print("H",i,"to O:",round(d,2),"to N14:",round(np.linalg.norm(pos[i]-pos[14]),2))
# H near N14
for i,e in enumerate(els):
    if e=="H":
        d=np.linalg.norm(pos[i]-pos[14])
